package app.jotday.calendar;

import org.json.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

/** Native parser for Jotday planning JSON and the supported iCalendar subset. */
final class CalendarImport {
    static final class Plan {final List<JSONObject> items=new ArrayList<>();final Set<String> warnings=new LinkedHashSet<>();}
    static Plan parse(String text)throws Exception{
        if(text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>2_000_000)throw new IllegalArgumentException("文件不得超过 2 MB");
        String raw=text.trim().replace("\uFEFF","");Plan plan=raw.startsWith("{")?json(Json.object(raw)):ics(raw);
        if(plan.items.isEmpty()||plan.items.size()>500)throw new IllegalArgumentException("一次请导入 1 至 500 项安排");
        for(JSONObject item:plan.items){if(item.optString("typeName").length()>40||item.optString("uid").length()>500)throw new IllegalArgumentException("分类名称或日程标识过长");}
        return plan;
    }
    private static Plan json(JSONObject data)throws Exception{
        if(data.optInt("version")!=1)throw new IllegalArgumentException("规划文件 version 必须为 1");Plan plan=new Plan();String zone=data.optString("timeZone","Asia/Hong_Kong");ZoneId.of(zone);
        for(String kind:new String[]{"event","todo"}){JSONArray rows=data.optJSONArray(kind+"s");if(data.has(kind+"s")&&rows==null)throw new IllegalArgumentException("events 和 todos 必须为数组");if(rows==null)continue;
            for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i),input=Json.copy(row);JSONObject item=Json.obj("kind",kind,"input",input);if(row.has("id"))Json.put(item,"uid","plan:"+row.optString("id"));if(row.has("type"))Json.put(item,"typeName",row.optString("type"));
                if(kind.equals("event")){Json.put(input,"timeZone",row.optString("timeZone",zone));Json.put(input,"allDay",row.optBoolean("allDay"));for(String key:new String[]{"start","end"})if(row.optString(key).length()==10)Json.put(input,key,row.optString(key)+"T00:00");validateEvent(input);}
                else{LocalDate.parse(row.getString("date"));if(row.optString("text").trim().isEmpty()||row.optString("text").length()>500||row.optString("notes").length()>10000)throw new IllegalArgumentException("待办名称或备注无效");if(!Json.str(row,"time").isEmpty())LocalTime.parse(row.getString("time"));JSONObject repeat=row.optJSONObject("repeat");if(repeat!=null){if(!Arrays.asList("daily","weekdays","weekly").contains(repeat.optString("kind")))throw new IllegalArgumentException("待办重复规则无效");if(repeat.optString("kind").equals("weekly")){JSONArray days=repeat.optJSONArray("weekdays");if(days==null||days.length()==0)throw new IllegalArgumentException("重复星期不能为空");for(int d=0;d<days.length();d++)if(days.optInt(d,-1)<0||days.optInt(d)>6)throw new IllegalArgumentException("重复星期无效");}}}
                plan.items.add(item);
            }
        }return plan;
    }
    private static final class Property{String key,value;Map<String,String> attrs=new HashMap<>();}
    private static List<Property> properties(List<Property> rows,String key){List<Property> out=new ArrayList<>();for(Property p:rows)if(p.key.equals(key))out.add(p);return out;}
    private static Property property(List<Property> rows,String key){for(Property p:rows)if(p.key.equals(key))return p;return null;}
    private static String value(List<Property> rows,String key){Property p=property(rows,key);return p==null?"":p.value;}
    private static String unescape(String text){return text.replace("\\n","\n").replace("\\N","\n").replace("\\,",",").replace("\\;",";").replace("\\\\","\\");}
    private static Plan ics(String text)throws Exception{
        if(!text.contains("BEGIN:VCALENDAR"))throw new IllegalArgumentException("请选择规划 JSON 或 ICS 日历");Plan plan=new Plan();List<List<Property>> events=new ArrayList<>();List<Property> current=null;boolean alarm=false;
        String unfolded=text.replace("\r\n","\n").replaceAll("\n[ \t]","");
        for(String line:unfolded.split("\n")){if(line.equals("BEGIN:VTODO"))throw new IllegalArgumentException("ICS 待办请转成规划 JSON 的 todos 数组");if(line.equals("BEGIN:VEVENT")){current=new ArrayList<>();events.add(current);continue;}if(line.equals("END:VEVENT")){current=null;continue;}if(current==null)continue;if(line.equals("BEGIN:VALARM")){alarm=true;plan.warnings.add("系统提醒不会导入");continue;}if(line.equals("END:VALARM")){alarm=false;continue;}if(alarm)continue;
            int split=line.indexOf(':');if(split<0)continue;String[] header=line.substring(0,split).split(";");Property p=new Property();p.key=header[0].toUpperCase(Locale.ROOT);p.value=line.substring(split+1);for(int a=1;a<header.length;a++){String[] pair=header[a].split("=",2);if(pair.length==2)p.attrs.put(pair[0].toUpperCase(Locale.ROOT),pair[1].replace("\"",""));}current.add(p);
        }
        Map<String,JSONObject> masters=new HashMap<>();
        for(List<Property> e:events){if(property(e,"RECURRENCE-ID")!=null)continue;if(value(e,"STATUS").equals("CANCELLED")){plan.warnings.add("已取消的日程未导入");continue;}String uid=value(e,"UID");if(!uid.isEmpty()&&masters.containsKey(uid))throw new IllegalArgumentException("ICS 含重复 UID");JSONObject input=readEvent(e,plan),exceptions=Json.obj();JSONObject item=Json.obj("kind","event","input",input,"exceptions",exceptions);if(!uid.isEmpty()){Json.put(item,"uid","ics:"+uid);masters.put(uid,item);}String category=value(e,"CATEGORIES");if(!category.isEmpty())Json.put(item,"typeName",unescape(category.split(",")[0]));
            for(Property excluded:properties(e,"EXDATE"))for(String date:excluded.value.split(","))Json.put(exceptions,dateInZone(excluded,date,input.optString("timeZone")).toLocalDate().toString(),null);plan.items.add(item);
        }
        for(List<Property> e:events){Property recurrence=property(e,"RECURRENCE-ID");if(recurrence==null)continue;JSONObject master=masters.get(value(e,"UID"));if(master==null||master.optJSONObject("input").optJSONObject("repeat")==null)throw new IllegalArgumentException("重复例外缺少主日程");if(recurrence.attrs.containsKey("RANGE"))throw new IllegalArgumentException("请将 THISANDFUTURE 例外拆成两个系列");String day=dateInZone(recurrence,recurrence.value,master.optJSONObject("input").optString("timeZone")).toLocalDate().toString();Json.put(master.optJSONObject("exceptions"),day,value(e,"STATUS").equals("CANCELLED")?null:readEvent(e,plan));}
        return plan;
    }
    private static String zone(Property p,String fallback){return p.value.endsWith("Z")?"UTC":p.attrs.getOrDefault("TZID",fallback);}
    private static LocalDateTime date(String value){String raw=value.endsWith("Z")?value.substring(0,value.length()-1):value;if(raw.matches("\\d{8}"))return LocalDate.parse(raw,DateTimeFormatter.BASIC_ISO_DATE).atStartOfDay();LocalDateTime time=LocalDateTime.parse(raw,DateTimeFormatter.ofPattern(raw.length()==13?"yyyyMMdd'T'HHmm":"yyyyMMdd'T'HHmmss"));if(time.getSecond()!=0)throw new IllegalArgumentException("当前日历精确到分钟，请移除秒数");return time;}
    private static LocalDateTime dateInZone(Property p,String raw,String target){LocalDateTime d=date(raw);if(raw.length()==8)return d;return d.atZone(ZoneId.of(raw.endsWith("Z")?"UTC":p.attrs.getOrDefault("TZID",target))).withZoneSameInstant(ZoneId.of(target)).toLocalDateTime();}
    private static JSONObject readEvent(List<Property> rows,Plan plan)throws Exception{
        Property s=property(rows,"DTSTART"),e=property(rows,"DTEND");if(s==null)throw new IllegalArgumentException("日程缺少 DTSTART");boolean allDay=s.value.length()==8;String zone=zone(s,"Asia/Hong_Kong");ZoneId.of(zone);LocalDateTime start=date(s.value),end;
        if(e!=null){if((e.value.length()==8)!=allDay)throw new IllegalArgumentException("起止时间格式不一致");end=dateInZone(e,e.value,zone);}else{String duration=value(rows,"DURATION");Duration length=duration.isEmpty()?Duration.ofMinutes(allDay?1440:60):duration.matches("P\\d+W")?Duration.ofDays(Long.parseLong(duration.substring(1,duration.length()-1))*7):Duration.parse(duration);if(length.getSeconds()%60!=0||length.isNegative()||length.isZero())throw new IllegalArgumentException("时长须为正整数分钟");end=allDay?start.plus(length):start.atZone(ZoneId.of(zone)).plus(length).toLocalDateTime();if(duration.isEmpty()&&!allDay)plan.warnings.add("缺少结束时间的行程使用 60 分钟时长");}
        if(property(rows,"RDATE")!=null||properties(rows,"RRULE").size()>1)throw new IllegalArgumentException("暂不支持 RDATE 或多个 RRULE");if(property(rows,"ATTENDEE")!=null||property(rows,"ATTACH")!=null)plan.warnings.add("参与人、邀请与附件不导入");
        JSONObject input=Json.obj("title",value(rows,"SUMMARY").isEmpty()?"未命名行程":unescape(value(rows,"SUMMARY")),"start",CalendarProjector.stamp(start),"end",CalendarProjector.stamp(end),"allDay",allDay,"timeZone",zone,"color","purple","notes",unescape(value(rows,"DESCRIPTION")),"location",unescape(value(rows,"LOCATION")),"url",unescape(value(rows,"URL")));
        if(property(rows,"RRULE")!=null)Json.put(input,"repeat",rule(value(rows,"RRULE"),start,zone));validateEvent(input);return input;
    }
    private static JSONObject rule(String raw,LocalDateTime start,String zone){Map<String,String> parts=new HashMap<>();for(String part:raw.split(";")){String[] p=part.split("=",2);if(p.length!=2)throw new IllegalArgumentException("重复规则无效");parts.put(p[0],p[1]);}for(String key:parts.keySet())if(!Arrays.asList("FREQ","INTERVAL","COUNT","UNTIL","BYDAY","BYMONTHDAY","BYMONTH","BYSETPOS","WKST").contains(key))throw new IllegalArgumentException("不支持重复规则："+key);if(parts.containsKey("WKST")&&!parts.get("WKST").equals("MO"))throw new IllegalArgumentException("重复规则目前从周一开始");String f=parts.getOrDefault("FREQ","").toLowerCase(Locale.ROOT);if(!Arrays.asList("daily","weekly","monthly","yearly").contains(f))throw new IllegalArgumentException("仅支持日、周、月、年重复");JSONObject r=Json.obj("frequency",f,"interval",Integer.parseInt(parts.getOrDefault("INTERVAL","1")));
        if(parts.containsKey("COUNT"))Json.put(r,"count",Integer.parseInt(parts.get("COUNT")));if(parts.containsKey("UNTIL")){String u=parts.get("UNTIL");LocalDateTime until=date(u);if(u.endsWith("Z"))until=until.atZone(ZoneId.of("UTC")).withZoneSameInstant(ZoneId.of(zone)).toLocalDateTime();if(u.length()>8&&until.toLocalTime().isBefore(start.toLocalTime()))until=until.minusDays(1);Json.put(r,"until",until.toLocalDate().toString());}
        if(f.equals("daily")&&(parts.containsKey("BYDAY")||parts.containsKey("BYMONTHDAY")||parts.containsKey("BYMONTH")||parts.containsKey("BYSETPOS")))throw new IllegalArgumentException("请先展开每日组合筛选规则");
        if(f.equals("weekly")&&(parts.containsKey("BYMONTHDAY")||parts.containsKey("BYMONTH")||parts.containsKey("BYSETPOS")))throw new IllegalArgumentException("每周规则不支持月份或序号筛选");if(f.equals("monthly")&&parts.containsKey("BYMONTH"))throw new IllegalArgumentException("每月规则不支持月份筛选");
        List<String> weekdays=Arrays.asList("SU","MO","TU","WE","TH","FR","SA");String byday=parts.get("BYDAY");if(f.equals("weekly")){JSONArray days=new JSONArray();if(byday==null)days.put(start.getDayOfWeek().getValue()%7);else for(String d:byday.split(",")){int index=weekdays.indexOf(d);if(index<0)throw new IllegalArgumentException("重复星期无效");days.put(index);}Json.put(r,"weekdays",days);}else if(byday!=null){java.util.regex.Matcher m=java.util.regex.Pattern.compile("^([+-]?\\d)?(SU|MO|TU|WE|TH|FR|SA)$").matcher(byday);if(!m.matches()||parts.containsKey("BYMONTHDAY")||f.equals("yearly")&&!parts.containsKey("BYMONTH"))throw new IllegalArgumentException("月／年星期组合规则需先展开");if(m.group(1)!=null&&parts.containsKey("BYSETPOS"))throw new IllegalArgumentException("星期序号不可重复");int ordinal=Integer.parseInt(m.group(1)==null?parts.getOrDefault("BYSETPOS","0"):m.group(1));if(ordinal!=-1&&(ordinal<1||ordinal>5))throw new IllegalArgumentException("星期序号无效");Json.put(r,"nthWeekday",Json.obj("ordinal",ordinal,"weekday",weekdays.indexOf(m.group(2))));}else if(parts.containsKey("BYSETPOS"))throw new IllegalArgumentException("不支持独立 BYSETPOS");
        for(String[] field:new String[][]{{"BYMONTHDAY","monthDays","31"},{"BYMONTH","months","12"}})if(parts.containsKey(field[0])){JSONArray a=new JSONArray();for(String v:parts.get(field[0]).split(",")){int n=Integer.parseInt(v);if(n<1||n>Integer.parseInt(field[2]))throw new IllegalArgumentException("重复日期超出范围");a.put(n);}Json.put(r,field[1],a);}return r;
    }
    static void validateEvent(JSONObject v){String title=v.optString("title");if(title.trim().isEmpty()||title.length()>240)throw new IllegalArgumentException("日程名称须为 1–240 字");LocalDateTime start=LocalDateTime.parse(v.optString("start")),end=LocalDateTime.parse(v.optString("end"));ZoneId zone=ZoneId.of(v.optString("timeZone","Asia/Hong_Kong"));if(!end.isAfter(start)||Duration.between(start,end).compareTo(Duration.ofDays(366))>0)throw new IllegalArgumentException("日程结束时间须晚于开始且不超过一年");if(!v.optBoolean("allDay")&&(zone.getRules().getValidOffsets(start).isEmpty()||zone.getRules().getValidOffsets(end).isEmpty()))throw new IllegalArgumentException("日程落在夏令时跳时中");String error=RepeatEditor.validate(v.optJSONObject("repeat"),start.toLocalDate());if(error!=null)throw new IllegalArgumentException(error);if(v.optString("notes").length()>4000||v.optString("location").length()>500||v.optString("url").length()>2000)throw new IllegalArgumentException("日程内容过长");if(!v.optString("url").isEmpty()&&!v.optString("url").matches("https?://.*"))throw new IllegalArgumentException("链接须以 http:// 或 https:// 开头");}
    static int[] apply(PlannerStore store,Plan plan){int[] counts={0,0};store.transaction(()->{Set<String> keys=new HashSet<>();for(String kind:new String[]{"event","link"})for(JSONObject row:store.all(kind))if(row.has("importKey"))keys.add(row.optString("importKey"));
        for(JSONObject item:plan.items){String kind=item.optString("kind"),key=kind+":"+(item.has("uid")?item.optString("uid"):Json.canonical(item));if(!keys.add(key)){counts[1]++;continue;}JSONObject input=Json.copy(item.optJSONObject("input"));String typeId=null,name=item.optString("typeName").trim();if(!name.isEmpty()){for(JSONObject t:store.all("type"))if(Json.str(t,"deletedAt").isEmpty()&&t.optString("name").equals(name)){typeId=t.optString("id");break;}if(typeId==null){typeId=UUID.randomUUID().toString();store.put("type",Json.obj("id",typeId,"workspaceId",store.workspace,"name",name,"color",input.optString("color","purple"),"rank",System.currentTimeMillis(),"deletedAt",null,"updatedAt",Instant.now().toString()));}}
            if(kind.equals("event")){JSONObject row=Json.obj("id",UUID.randomUUID().toString(),"workspaceId",store.workspace,"deletedAt",null,"updatedAt",Instant.now().toString(),"exceptions",item.optJSONObject("exceptions")==null?Json.obj():item.optJSONObject("exceptions"),"importKey",key,"typeId",typeId,"color","purple","notes","","location","","url","");for(String field:new String[]{"title","start","end","allDay","timeZone","color","notes","location","url","repeat"})if(input.has(field))Json.put(row,field,input.opt(field));store.put("event",row);}
            else{JSONObject todo=WorkspaceRecords.task(store,input.optString("text"),LocalDate.parse(input.optString("date")),input.optString("notes"));JSONObject p=todo.optJSONObject("planning"),repeat=input.optJSONObject("repeat");if(repeat!=null){Json.put(p,"kind","series");Json.put(p,"revisions",new JSONArray().put(Json.obj("id",UUID.randomUUID().toString(),"effectiveFrom",input.optString("date"),"changedAt",Instant.now().toString(),"text",input.optString("text"),"notes",input.optString("notes"),"repeat",repeat,"paused",false,"stopped",false)));}WorkspaceRecords.save(store,"todo",todo);String id=todo.optString("id");store.put("link",Json.obj("id",store.workspace+":"+id,"workspaceId",store.workspace,"todoId",id,"typeId",typeId,"time",input.opt("time"),"importKey",key,"updatedAt",Instant.now().toString()));}counts[0]++;
        }
    });return counts;}
}
